const {chromium}=require('playwright'); const fs=require('fs');const path=require('path');const assert=require('assert/strict');
(async()=>{const dir=process.env.ATRIUM_QUALITY_TEST;assert(dir,'ATRIUM_QUALITY_TEST 必须指向临时目录');let info;for(let i=0;i<100;i++){try{info=JSON.parse(fs.readFileSync(dir+'/ready.json'));break}catch{}await new Promise(r=>setTimeout(r,100))}assert(info,'server ready');
const expected={complete:'每次交付 USD 3（完整读数 2/2）',partial:'已知合计 USD 2（完整读数 1/3；每次交付未知）',missing:'未知（完整读数 0/1）',zero:'每次交付 USD 0（完整读数 1/1）',currency:'每次交付 USD 1.5（完整读数 2/2）',bad:'未知（完整读数 0/3）'};
const cli=JSON.parse(fs.readFileSync(dir+'/cli.json')); const rows=cli.result;
for(const [name,text]of Object.entries(expected)){assert.equal(rows.find(q=>q.combo==='codex+'+name).cost_text,text);assert(fs.readFileSync(dir+'/cli.txt','utf8').includes(text));}
const browser=await chromium.launch({headless:true});try{const page=await browser.newPage({viewport:{width:1280,height:900}});const errors=[];page.on('pageerror',e=>errors.push(e.message));for(const[name,text]of Object.entries(expected)){const r=await fetch(info.base+'/ui/api/worker?name=codex%2B'+name);assert.equal(r.status,200);assert.equal((await r.json()).result.quality.cost_text,text);await page.goto(info.base+'/#legion/codex%2B'+name);await page.getByText('近 30 天花费：'+text,{exact:true}).waitFor({timeout:10000});await page.waitForTimeout(400);await page.screenshot({path:dir+'/'+name+'.png'});}assert.deepEqual(errors,[]);fs.writeFileSync(dir+'/browser.txt','六种样本 CLI 文本/JSON、网页 API、无头实际抽屉一致；无 pageerror\n');}finally{await browser.close();fs.writeFileSync(dir+'/done','ok');}})().catch(e=>{console.error(e);process.exitCode=1});
